// See apps/k7-daw-frontend/packages/song-video/docs/transitions.md and apps/k7-daw-wasm/song/docs/chainFiles.md.
start(true)
steps([id("$UUID1").track("main"), to([chain("glow")])])
subchains([
  id("iris").steps([id("$UUID2").extends("@workspace/shaders/iris")]),
])

extends("@meta/picture-track")
// the camera
events([
  ref("shot_a").start(0).length(4),
  ref("shot_b").start(4).length(6).from(2.5).animate({ opacity: [[1, 0]] }),
])

args:
// pads: a MIDI device — the notes a lane records, when this node is wired to it (docs/midiIn.md).
//
// Pick the device on the node's card, or write its LABEL here — never an id, which is per
// browser. Empty records from any device:
//
//     device("Arturia KeyStep 37")
io("midi")

vectors.ret:
// The PICTURE's run: RENDER is where the lanes composite and VIDEO_OUT is the frame that leaves.
// Neither carries a param — a frame has no level. See apps/k7-daw-wasm/song/docs/videoOutputs.md.
start("RENDER")
steps([to([chain("VIDEO_OUT")])])

// A LIVE rig: something plugged in, heard through this machine.
//
// It declares no `surfaces/` — no timeline, no viewport, no desk — and that is the whole
// of what makes it this shape rather than another. A project draws what it DECLARES, so
// this one opens on its graph and nothing else. See apps/k7-daw-wasm/song/docs/liveProject.md.
//
// It holds no material either: no `clips/`, no `sequences/`. Nothing is arranged, so
// nothing warns about an arrangement that is not drawn.
project({
  name: "live",
  // Kept although nothing is arranged: the metronome counts in it, and so does a
  // delay whose time is written in beats.
  tempo: 120,
  sampleRate: 48000,
})

args:
// s1: one use of module "audio/squash".
// It inherits everything that module says — state only what THIS use changes, e.g.
//   params({ "Filter Freq": 69 })
extends("@workspace/audio/squash")

vectors.ret:
// ma soirée
title("set")
items(["AC-DC/Back in Black/Hells Bells"])

args:
// squash: one use of module "audio/comp".
// It inherits everything that module says — state only what THIS use changes, e.g.
//   params({ "Filter Freq": 69 })
extends("@project/audio/comp")

vectors.ret:
// The ARRANGEMENT — the timeline, and the transport that rolls through it.
//
// A project draws one because it says so here: the timeline is a SURFACE
// (apps/k7-daw-wasm/song/docs/surfaces.md), not something the editor hands out for free. Take this
// file away and the song still compiles and still plays — you simply have no lanes on screen.
//
// `split` is what puts it in the layout, sharing the window with the graph underneath, and is
// the only layout a timeline draws in. `view` is the other one: a screen of its own off the
// header, which is where a turntables desk goes.
type("timeline")
layout("split")

// A SHAPE is a picture source: it starts the chain of the lane it draws on, as a camera would.
// See apps/k7-daw-frontend/packages/song-video/docs/shapes.md.
start(true)
steps([
  id("$UUID1").extends("@workspace/shapes/title"),
  id("$UUID2").track("title_layer"),
  id("$UUID3").extends("@meta/shaders/video-mixer"),
  to([chain("RENDER")]),
])

// A SHAPE is a picture source: it starts the chain of the lane it draws on, as a camera would.
// See apps/k7-daw-frontend/packages/song-video/docs/shapes.md.
start(true)
steps([
  id("$UUID1").extends("@workspace/shapes/title"),
  id("$UUID2").track("title_layer"),
])

// turntableA — one @k7-core/turntable. Its members are ordinary nodes; this file is what draws them as a box.
uses("@k7-core/turntable")
members({ deck: "turntableA_deck", fade: "turntableA_fade" })

args:
// verb2n: one use of module "audio/verb2".
// It inherits everything that module says — state only what THIS use changes, e.g.
//   params({ "Filter Freq": 69 })
extends("@workspace/audio/verb2")

// verb3n: one use of module "audio/verb3".
// It inherits everything that module says — state only what THIS use changes, e.g.
//   params({ "Filter Freq": 69 })
extends("@workspace/audio/verb3")

vectors.ret:
// The FRAME — this song's three video lanes composited with WebGL, drawn against the
// engine's playhead.
//
// `floating` is the only layout it draws in: a window over whichever page is on screen,
// moved by its title bar and sized by its corner. `ui viewport` shows or hides it; hidden,
// it keeps its GL context and its <video> per layer, so showing it again costs nothing.
//
// Take this file away and the lanes still compile and still draw on the timeline — nothing
// composites them, and `surfaceIssues` says so. See apps/k7-daw-wasm/song/docs/surfaces.md.
type("viewport")
layout("floating")

